function rowsOf(nodeName) {
  const root = $(nodeName).first()?.json ?? {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.data)) return root.data;
  if (Array.isArray(root.items)) return root.items;
  if (Array.isArray(root.results)) return root.results;
  return [];
}
function contentId(row) {
  return String(row.content_id ?? row.contentId ?? row.video_id ?? row.videoId ?? row.contentID ?? row.id ?? '');
}
function competitorId(row) {
  return row.competitor_id ?? row.competitorId ?? row.competitor?.id ?? null;
}
function competitorName(row) {
  return String(row.competitor_name ?? row.competitorName ?? row.name ?? row.competitor?.name ?? 'Unknown competitor');
}
function toNum(v) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

const performance = rowsOf('02 - Get Performance KPI');
const activity = rowsOf('03 - Get Monitoring Activity');
const analyses = rowsOf('04 - Get Content Analysis');
const contentTopic = new Map();
for (const a of analyses) contentTopic.set(String(a.content_id ?? a.contentId ?? a.id ?? ''), String(a.topic ?? a.category ?? 'Unknown topic'));
const groups = new Map();
function ensure(id, name, platform) {
 const key = String(id ?? name ?? 'unknown');
 if (!groups.has(key)) groups.set(key,{competitor_id:id ?? null,competitor_name:name ?? 'Unknown competitor',platform:platform ?? 'unknown',video_count:0,total_views:0,total_likes:0,total_comments:0,total_engagement:0,activity_count:0,view_spikes:[],like_spikes:[],comment_spikes:[],topics:new Map(),evidence:[]});
 return groups.get(key);
}
for (const p of performance) {
 const id=competitorId(p), name=competitorName(p), g=ensure(id,name,p.platform);
 g.video_count++;
 g.total_views+=toNum(p.views); g.total_likes+=toNum(p.likes); g.total_comments+=toNum(p.comments);
 const cid=contentId(p); if(cid) g.evidence.push(cid);
 const topic=contentTopic.get(cid); if(topic) g.topics.set(topic,(g.topics.get(topic)||0)+1);
}
for (const a of activity) {
 const id=competitorId(a), name=competitorName(a), g=ensure(id,name,a.platform);
 const metrics=Array.isArray(a.metrics)?a.metrics:[];
 const latest=metrics[0]??{}, previous=metrics[1]??{};
 const pct=(cur,prev)=>toNum(prev)>0?Number(((toNum(cur)-toNum(prev))/toNum(prev)*100).toFixed(2)):(toNum(cur)>0?null:0);
 const v=pct(latest.views,previous.views), l=pct(latest.likes,previous.likes), c=pct(latest.comments,previous.comments);
 g.activity_count++;
 if(v!==null && v>=100) g.view_spikes.push({content_id:a.contentId??a.content_id, growth_rate:v});
 if(l!==null && l>=100) g.like_spikes.push({content_id:a.contentId??a.content_id, growth_rate:l});
 if(c!==null && c>=100) g.comment_spikes.push({content_id:a.contentId??a.content_id, growth_rate:c});
 const cid=String(a.contentId??a.content_id??''); const topic=contentTopic.get(cid); if(topic) g.topics.set(topic,(g.topics.get(topic)||0)+1);
 if(cid) g.evidence.push(cid);
}
if (!groups.size) throw new Error('Không có KPI hoặc activity data. Hãy chạy WF01-WF05 trước.');
return [...groups.values()].map(g=>{
 const er=g.total_views>0?Number(((g.total_likes+g.total_comments)/g.total_views*100).toFixed(2)):0;
 const topTopics=[...g.topics.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([topic,count])=>({topic,count}));
 const indicators=[];
 if(g.video_count>=10) indicators.push('high_content_volume');
 if(g.view_spikes.length) indicators.push('views_spike_100_percent_or_more');
 if(g.like_spikes.length) indicators.push('likes_spike_100_percent_or_more');
 if(g.comment_spikes.length) indicators.push('comments_spike_100_percent_or_more');
 return {json:{competitor_id:g.competitor_id,competitor_name:g.competitor_name,platform:g.platform,video_count:g.video_count,total_views:g.total_views,total_likes:g.total_likes,total_comments:g.total_comments,engagement_rate:er,activity_count:g.activity_count,view_spikes:g.view_spikes,like_spikes:g.like_spikes,comment_spikes:g.comment_spikes,top_topics:topTopics,risk_indicators:indicators,evidence:[...new Set(g.evidence)].slice(0,12),ai_prompt: `You are an evidence-based competitive risk analyst.

Analyze the supplied data to determine whether a competitor presents a significant competitive threat. Use only the available evidence.

OUTPUT REQUIREMENTS:
- Return exactly one valid JSON object.
- Do not use Markdown or code fences.
- Do not include any text outside the JSON object.
- Write all text values in Vietnamese.
- has_risk: boolean (true or false).
- title: a short, meaningful risk title in Vietnamese.
- severity: "HIGH", "MEDIUM", or "LOW".
- score: an integer from 0 to 100.
- reason: a concise explanation in Vietnamese, supported by the data.

ASSESSMENT RULES:
- Consider rapid content growth, changes in popular topics, engagement trends, and unusually large increases in views, likes, or comments.
- Base every conclusion on the supplied evidence.
- Do not invent statistics, historical trends, or explanations unsupported by the data.
- If historical data is limited or missing, reduce the score and mention the limitation in Vietnamese.
- HIGH severity: score >= 80.
- MEDIUM severity: score >= 60 and < 80.
- LOW severity: score < 60.
- Set has_risk to true only when the evidence indicates a meaningful competitive threat.
- Keep the output concise.

DATA:
${JSON.stringify({competitor_id:g.competitor_id,competitor_name:g.competitor_name,platform:g.platform,video_count:g.video_count,total_views:g.total_views,total_likes:g.total_likes,total_comments:g.total_comments,engagement_rate:er,activity_count:g.activity_count,view_spikes:g.view_spikes,like_spikes:g.like_spikes,comment_spikes:g.comment_spikes,top_topics:topTopics,risk_indicators:indicators,evidence:[...new Set(g.evidence)].slice(0,12)})}`}};
});

function parseAI(value) {
  if (value && typeof value === 'object') return value;

  if (typeof value === 'string') {
    const cleaned = value
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    return JSON.parse(cleaned);
  }

  throw new Error('AI Risk Analysis không trả về JSON hợp lệ.');
}

const aiItems = $input.all();
const bases = $('05 - Build Risk Indicators').all();

return aiItems.map((item, i) => {
  const b = bases[i]?.json;

  if (!b) {
    throw new Error(`Thiếu risk context ${i}`);
  }

  const r = item.json;

  const txt =
  typeof r.content === 'string'
    ? r.content
    : r.content?.parts?.[0]?.text ??
      r.output?.[0]?.content?.[0]?.text ??
      r.output?.[0]?.content?.text ??
      r.text ??
      r.message?.content;

  const a = parseAI(txt);

  const score = Math.round(
    Math.max(0, Math.min(100, Number(a.score ?? 0)))
  );

  const severity = ['HIGH', 'MEDIUM', 'LOW'].includes(
    String(a.severity ?? '').toUpperCase()
  )
    ? String(a.severity).toUpperCase()
    : score >= 80
      ? 'HIGH'
      : score >= 60
        ? 'MEDIUM'
        : 'LOW';

  return {
    json: {
      title: String(
        a.title ?? `${b.competitor_name} Competitive Risk`
      ),
      score,
      severity,
      reason: String(
        a.reason ?? 'Đánh giá từ KPI và hoạt động đối thủ.'
      ),
      evidence: b.evidence,
      competitor_id: b.competitor_id,
      competitor_name: b.competitor_name,
      created_at: new Date().toISOString(),
      has_risk: a.has_risk === true && score >= 50
    }
  };
});
